import { getCrmebCopyRight } from "@/api/system";
export default {
  name: "i-copyright",
  data: function data() {
    return {
      links: [{
        title: "官网",
        key: "官网",
        href: "https://www.crmeb.com",
        blankTarget: true
      }, {
        title: "社区",
        key: "社区",
        href: "http://www.crmeb.com/ask",
        blankTarget: true
      }, {
        title: "文档",
        key: "文档",
        href: "http://doc.crmeb.com",
        blankTarget: true
      }],
      copyright: ""
    };
  },
  mounted: function mounted() {
    this.getCopyRight();
  },
  methods: {
    //获取版权信息
    getCopyRight: function getCopyRight() {
      var _this = this;
      getCrmebCopyRight().then(function (res) {
        if (res.data.copyrightContext) {
          _this.links = [];
        }
        var copyrightText = res.data.copyrightContext ? res.data.copyrightContext : "Copyright © 2014-2024 ";
        _this.$store.dispatch("admin/db/get", {
          dbName: "sys",
          path: "user.info",
          user: true
        }).then(function (data) {
          copyrightText += data.version && !res.data.copyrightContext ? data.version : "";
          _this.copyright = copyrightText;
        });
      });
    }
  }
};
